import logging
import subprocess
import time
from select import select, error
from taf.internal.execution.base import Process, InputStream, OutputStream, TimeoutError


logger = logging.getLogger(__name__)
logger.addHandler(logging.NullHandler())


class LocalProcess(Process):
    """
    Running process with input and output streams.
    """

    def __init__(self, popen, **kwargs):
        super(LocalProcess, self).__init__(**kwargs)
        self._popen = popen

    def wait(self, timeout=None):
        """
        Wait until the process finishes execution.

        :param float timeout:
            wait timeout seconds for the process to finish
            (forever, if timeout is None)
        :raises: TimeoutError, if process did not finish after timeout seconds
        """
        try:
            self._popen.wait(timeout=timeout)
        except subprocess.TimeoutExpired:
            raise TimeoutError(self._command, timeout)

    def _get_is_running(self):
        """
        Return True, if the process is still running.

        :return:
        """
        return self._popen.poll() is None

    def _get_exit_status(self):
        """
        Return the exit status of a terminated process.

        :return: exit status
        :rtpye: int
        """
        return self._popen.returncode

    def _read_output(self):
        """
        Read stdout and stderr from the process without logging.

        Uses select() to multiplex between the two streams to avoid blocking.

        :return: stdout data, stderr data
        :rtype: bytes, bytes
        """
        stdout_fd = self.stdout.fileno()
        stderr_fd = self.stderr.fileno()
        stdout_data = bytearray()
        stderr_data = bytearray()
        closed_stdout = False
        closed_stderr = False

        while not (closed_stdout and closed_stderr):
            rlist, _, _ = select([stdout_fd, stderr_fd], [], [], None)

            if stdout_fd in rlist:
                data = self.stdout.read(4096)
                if not data:
                    closed_stdout = True
                else:
                    stdout_data.extend(data)

            if stderr_fd in rlist:
                data = self.stderr.read(4096)
                if not data:
                    closed_stderr = True
                else:
                    stderr_data.extend(data)

        return bytes(stdout_data), bytes(stderr_data)


class LocalStream(object):
    """
    Base class for streams of local executor.
    """

    def __init__(self, file, **kwargs):
        """
        Create a LocalStream.

        :param file file: file object
        """
        super(LocalStream, self).__init__(**kwargs)
        self._file = file

    def fileno(self):
        """
        Return the file descriptor of the underlying file.

        :return: file descriptor
        :rtype: int
        """
        return self._file.fileno()


class LocalInputStream(InputStream, LocalStream):
    """
    Input stream of a local process (stdin), where input data can be written to.
    """

    def write(self, data):
        """
        Write data to stream.

        :param bytes data: data to be written into the input stream
        """
        logger.debug("writing {data!r} to input stream".format(data=data))
        self._file.write(data)

    def close(self):
        """
        Close the input stream.
        """
        logger.debug("closing")
        self._file.close()


class LocalBaseOutputStream(OutputStream, LocalStream):
    """
    Base class for output streams of local process.
    """

    def _read(self, size=None, timeout=None):
        """
        Read data from stream.

        :param int size: maximum number of bytes to read (read all data, if size is None)
        :param float timeout: timeout in seconds to wait for the next character

        :return: read data
        :rtype: bytes
        """
        self._start_time = time.time()
        if size is None:
            data = b""
            while True:
                self._wait_for_readable(timeout=timeout)
                new_data = self._file.read()
                if not new_data:
                    return data
                data += new_data
        else:
            self._wait_for_readable(timeout=timeout)
            return self._file.read(size)

    def _wait_for_readable(self, timeout):  # noqa: C901
        fd = self._file.fileno()
        while True:
            try:
                if timeout is None:
                    rlist, _, _ = select([fd], [], [], None)
                    return
                time_elapsed = time.time() - self._start_time
                if timeout >= time_elapsed:
                    rlist, _, _ = select([fd], [], [], timeout - time_elapsed)
                    if fd in rlist:
                        return
                raise TimeoutError()
            except error as e:
                logger.debug('Avoiding select.error: {}'.format(e))


class LocalOutputStream(LocalBaseOutputStream):
    """
    Output stream of a local process (stdout), where output data can be read from.
    """

    _stream_name = "stdout"


class LocalErrorStream(LocalBaseOutputStream):
    """
    Error stream of a local process (stderr), where error data can be read from.
    """

    _stream_name = "stderr"
